"""Customers: profile records."""

TABLE = "profile"
FIELDS = ('customer_id', 'phone', 'birthday')


def ensure_table(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS profile (id INTEGER PRIMARY KEY, customer_id TEXT, phone TEXT, birthday TEXT)")


def create(conn, customer_id, phone, birthday):
    ensure_table(conn)
    cur = conn.execute("INSERT INTO profile(customer_id, phone, birthday) VALUES (?,?,?)", (customer_id, phone, birthday,))
    conn.commit()
    return cur.lastrowid


def get(conn, row_id):
    ensure_table(conn)
    return conn.execute("SELECT * FROM profile WHERE id=?", (row_id,)).fetchone()


def list_all(conn, limit=100):
    ensure_table(conn)
    return conn.execute("SELECT * FROM profile ORDER BY id LIMIT ?", (limit,)).fetchall()


def update(conn, row_id, **changes):
    ensure_table(conn)
    bad = set(changes) - set(FIELDS)
    if bad:
        raise ValueError(f"unknown fields {sorted(bad)}")
    for k, v in changes.items():
        conn.execute(f"UPDATE profile SET {k}=? WHERE id=?", (v, row_id))
    conn.commit()


def delete(conn, row_id):
    ensure_table(conn)
    conn.execute("DELETE FROM profile WHERE id=?", (row_id,))
    conn.commit()


def normalize_phone(phone):
    digits = "".join(c for c in phone if c.isdigit())
    return "+84" + digits[1:] if digits.startswith("0") else "+" + digits
